<?php require_once __DIR__.'/../includes/functions.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'){$d=json_decode(file_get_contents('php://input'),true)?:$_POST;if(($d['action']??'')==='read'){$s=$pdo->prepare("UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?");$s->execute([(int)$d['id'],$_SESSION['user']['id']]);json_response(true,'Notification marked read');}}$s=$pdo->prepare("SELECT id,title,message,is_read,created_at FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 20");$s->execute([$_SESSION['user']['id']]);json_response(true,'OK',['notifications'=>$s->fetchAll()]);